def source_low(value):
    if not isinstance(value,str):
        value=str(value)
    return value.casefold().strip()

def source_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def source_add(out,term,support_ids):
    support=source_unique(support_ids)
    for row in out:
        if isinstance(row,dict) and row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def source_has(term,name):
    todo=[term]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            if item[0]==name:
                return True
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return False

def source_material(copies,derivatives):
    value=['confidential_information']
    if copies:
        value=['information_bundle',value,['copies_of',['confidential_information']]]
    if derivatives:
        value=['information_bundle',value,['derivative_materials_of',['confidential_information']]]
    return value

def source_find_after(spans,index,phrases,limit):
    stop=min(len(spans),index+limit+1)
    i=index+1
    while i<stop:
        text=source_low(spans[i].get('text',''))
        for phrase in phrases:
            if phrase in text:
                return i
        i+=1
    return -1

def source_exception_after(spans,index,limit):
    backup=''
    legal=''
    ids=[]
    stop=min(len(spans),index+limit+1)
    i=index+1
    while i<stop:
        raw=spans[i].get('text','')
        if not isinstance(raw,str):
            raw=str(raw)
        text=source_low(raw)
        if not backup and ('back-up/archival' in text or 'backup/archival' in text):
            backup=raw
            ids.append(spans[i].get('id'))
        if not legal and 'single copy' in text and ('legal department' in text or 'dispute resolution' in text):
            legal=raw
            ids.append(spans[i].get('id'))
        i+=1
    if backup and legal:
        return ['backup_archive_and_legal_record',backup,legal,source_unique(ids)]
    if backup:
        return ['backup_archive',backup,'',source_unique(ids)]
    if legal:
        return ['legal_dispute_record','',legal,source_unique(ids)]
    return ['no_acquired_exception','','',[]]

def source_false_mixed_request_root(row,by_id):
    if not isinstance(row,dict):
        return False
    term=row.get('term')
    if not isinstance(term,list) or not term or term[0]!='disposal_obligation':
        return False
    if not source_has(term,'action_alternative') or not source_has(term,'request_by'):
        return False
    parts=[]
    for uid in row.get('support_ids',[]):
        raw=by_id.get(uid,'')
        if not isinstance(raw,str):
            raw=str(raw)
        parts.append(raw)
    text=source_low(' '.join(parts))
    return 'returned to the disclosing party upon request or destroyed within' in text and 'project' in text
